// Turn the form answers into a Claude "AI director" request.
const f = $input.first().json;
const SYSTEM = "You are a video director. You receive a narration script and break it into a storyboard for an automatically produced voiceover video.\n\nRules:\n- Keep the author's wording. Copy the script into `narration` scene by scene; only make light edits for speakability (expand abbreviations, fix obvious typos) unless the user explicitly asks for a rewrite.\n- Drop stage directions, headings and notes like \"[music]\" or \"SCENE 1:\" from narration.\n- Each scene should take 4-12 seconds to speak (roughly 10-30 words). Split long paragraphs.\n- `stock_query`: 2-4 concrete, filmable words for a stock-footage search (e.g. \"tailor sewing fabric\", not \"craftsmanship\").\n- `image_prompt`: one vivid sentence describing the ideal shot (subject, setting, lighting, camera), usable by an image generator. No text in the image.\n- `on_screen_text`: a short punchy headline (max 6 words) for scenes that benefit from one - the opening, key points, and the call to action. Use an empty string otherwise.\n- `mood`: one word (e.g. calm, energetic, luxurious, dramatic, warm).\n- `title`: a short title for the whole video.";
const SCHEMA = {
  "type": "object",
  "additionalProperties": false,
  "required": [
    "title",
    "scenes"
  ],
  "properties": {
    "title": {
      "type": "string"
    },
    "scenes": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "narration",
          "on_screen_text",
          "stock_query",
          "image_prompt",
          "mood"
        ],
        "properties": {
          "narration": {
            "type": "string"
          },
          "on_screen_text": {
            "type": "string"
          },
          "stock_query": {
            "type": "string"
          },
          "image_prompt": {
            "type": "string"
          },
          "mood": {
            "type": "string"
          }
        }
      }
    }
  }
};

const notes = [];
if (f.style) notes.push(`Visual style / brand notes: ${f.style}`);
if ((f.rewrite || '').startsWith('Yes')) notes.push('You MAY rewrite the narration to be tighter and more engaging.');
const content = [...notes, 'Script:', '<script>', String(f.script || '').trim(), '</script>'].join('\n');

return [{
  json: {
    form: {
      script: f.script,
      aspect: String(f.format || '9:16').split(' ')[0],
      voice: f.voice || 'auto',
      style: f.style || '',
      music_url: f.music_url || '',
    },
    request: {
      model: 'claude-opus-5-5',
      max_tokens: 16000,
      system: SYSTEM,
      messages: [{ role: 'user', content }],
      output_config: { effort: 'medium', format: { type: 'json_schema', schema: SCHEMA } },
      fallbacks: 'default',
    },
  },
}];

// Validate Claude's storyboard and build the render request.
const res = $input.first().json;
const form = $('Build Claude Request').first().json.form;

if (res.stop_reason === 'refusal') throw new Error('Claude declined to plan this script.');
if (res.stop_reason === 'max_tokens') throw new Error('Storyboard was cut off - try a shorter script.');
const text = (res.content || []).filter(b => b.type === 'text').map(b => b.text).join('');
const storyboard = JSON.parse(text);
if (!Array.isArray(storyboard.scenes) || storyboard.scenes.length === 0) {
  throw new Error('Claude returned a storyboard with no scenes.');
}

const render = { storyboard, aspect: form.aspect, voice: form.voice, style: form.style };
if (form.music_url) render.music_url = form.music_url;
return [{ json: { storyboard, render } }];
